+  };
+  const invoke = (surface: CurrentObservationSurface, minimum: TransactionMinimum, page: string, target?: string, principal = "p") => {
+    if (surface === "page") return service.receiptPage({ kind: "authenticated", principal }, target ?? page, minimum);
+    if (surface === "discovery") return service.discoveryObserved(minimum);
+    const request = requestFromUrl(new URL(target ?? (surface === "type" ? "types/task" : surface === "types" ? "types/" : "beads/a?view=links"), scope), scope);
